source('mp10_immune_endothelial_mechanisms_v1/scripts/common.R');checks<-list();check<-function(name,pass,detail=''){checks[[length(checks)+1]]<<-data.table(check=name,pass=isTRUE(pass),detail=as.character(detail))}
b<-qread(file.path(B,'objects/pseudobulk.qs'),nthreads=1);pr<-b$profiles;a<-rd('analysis_cell_metadata.tsv.gz');md<-rd('source_cell_metadata.tsv.gz');q<-rd('specimen_exposure_eligibility.tsv');m<-rd('pseudobulk_membership.tsv.gz');check('analysis_barcodes_unique',!anyDuplicated(a$barcode));check('all_barcodes_in_source',all(a$barcode%in%md$barcode));orig<-md[match(a$barcode,barcode)];check('barcode_dataset_matches',all(orig$dataset==a$dataset));check('barcode_specimen_matches',all(paste(orig$dataset,orig$orig.ident,sep='::')==a$sample_uid));check('original_40_specimens',uniqueN(a$sample_uid)==40);check('original_Epi_116448',sum(a$analysis_major_c2l_final=='Epithelial')==116448)
check('PB_columns_metadata_order',identical(colnames(b$counts),pr$profile_id));check('PB_gene_domain_90011',nrow(b$counts)==90011&&identical(rownames(b$counts),b$feature_universe));check('PB_nonnegative_integer',all(b$counts@x>=0 & b$counts@x==round(b$counts@x)));check('PB_total_counts',all(Matrix::colSums(b$counts)==pr$total_counts));check('PB_detected_genes',all(Matrix::colSums(b$counts>0)==pr$detected_genes));n<-m[,.N,by=profile_id];check('PB_membership_cell_counts',all(n$N==pr$n_cells[match(n$profile_id,pr$profile_id)]));check('TME_not_duplicated_High_Low',!anyDuplicated(m[!profile_type%in%c('Epi_all','L50','H50','H10','H05'),barcode]));check('detection_counts_not_exceed_cells',all(vapply(seq_len(ncol(b$detected_cells)),function(j){lo<-b$detected_cells@p[j]+1L;hi<-b$detected_cells@p[j+1L];if(lo>hi)TRUE else all(b$detected_cells@x[lo:hi]<=pr$n_cells[j])},logical(1))))
for(s in q$sample_uid){ee<-a[sample_uid==s&analysis_major_c2l_final=='Epithelial'];qq<-quantile(ee$MP10_cell,c(.5,.9,.95),type=7);check(paste0('frozen_quantiles:',s),max(abs(qq-as.numeric(unlist(q[sample_uid==s,.(Q50,Q90,Q95)]))))<1e-12);mm<-m[sample_uid==s];check(paste0('nested_High_pools:',s),all(mm[profile_type=='H05',barcode]%in%mm[profile_type=='H10',barcode])&&all(mm[profile_type=='H10',barcode]%in%mm[profile_type=='H50',barcode]));check(paste0('Low_disjoint_High:',s),!any(mm[profile_type=='L50',barcode]%in%mm[profile_type=='H50',barcode]))}
st<-rd('model_status.tsv');mem<-rd('model_membership.tsv.gz');for(i in seq_len(nrow(st))){p<-st[i];sel<-mem[model_id==p$model_id];if(!nrow(sel))next;check(paste0('patient_selection:',p$model_id),if(p$patient=='main')!any(grepl('T4463209b',sel$specimen_id))else!any(grepl('T4463209a',sel$specimen_id)));check(paste0('one_recorded_patient_unit:',p$model_id),uniqueN(sel$sample_uid)==uniqueN(sel$patient_uid_recorded));check(paste0('cell_threshold:',p$model_id),all(sel$n_cells>=p$min_cells));if(p$status=='completed'){check(paste0('full_rank_df:',p$model_id),p$design_rank==p$design_columns&&p$residual_df>=3);d<-rd(paste0('de/',p$model_id,'.tsv.gz'));check(paste0('DE_P_FDR:',p$model_id),all(is.finite(d$PValue)&d$PValue>=0&d$PValue<=1)&max(abs(p.adjust(d$PValue,'BH')-d$FDR))<1e-12);check(paste0('finite_signed_ranking:',p$model_id),all(is.finite(d$signed_stat)));if(p$kind=='Epi')check(paste0('paired_specimens:',p$model_id),all(sel[,.N,by=sample_uid]$N==2))else check(paste0('receiver_not_duplicated:',p$model_id),!anyDuplicated(sel$sample_uid))}}
if(file.exists(tb('nichenet_target_background_checks.tsv'))){z<-rd('nichenet_target_background_checks.tsv');check('NicheNet_target_subset',all(z$subset_background));check('NicheNet_M20_mask',all(z$masked_excludes_M20));check('NicheNet_target_counts',all(z$count_matches))}
if(file.exists(file.path(B,'config/figure_manifest.tsv'))){fm<-fread(file.path(B,'config/figure_manifest.tsv'));check('figure_files_exist',all(file.exists(fm$file)));check('figure_direct_data_exist',all(file.exists(fm$data_file)))}
